            wsReport.Cells[startRow, startCol + (nextCol2 += 1)].Style = bgHeaderNormalFormat;
            wsReport.Cells[startRow, startCol + nextCol2].Value =
                ResourceExtension.GetResourceValue(ResourceExtension.Resources.Language, "Master");
            wsReport.Cells[startRow, startCol + (nextCol2 += 1)].Style = bgHeaderNormalFormat;
            wsReport.Cells[startRow, startCol + nextCol2].Value =
                ResourceExtension.GetResourceValue(ResourceExtension.Resources.Language, "Super");
            wsReport.Cells[startRow, startCol + (nextCol2 += 1)].Style = bgHeaderNormalFormat;
            wsReport.Cells[startRow, startCol + nextCol2].Value =
                ResourceExtension.GetResourceValue(ResourceExtension.Resources.Language, "Company");

            #endregion second row
        }

        private void ExportExcelWinlostP2PDetailAssignContent(int startCol, int startRow, ref ExcelWorksheet wsReport, ref int nextRow, List<PokerRow> pokerRows)
        {
            var bgColor = Color.FromArgb(255, 255, 255);
            var bgFormat = new Core.Helper.ExcelGemboxUtils().GetStyleIntNumber(".00", bgColor, false, false);
            var bgFormatNegative = new Core.Helper.ExcelGemboxUtils().GetStyleIntNumber(".00", bgColor, false, false, true);
            if (pokerRows != null && pokerRows.Count > 0)
            {
                foreach (var pokerRow in pokerRows)
                {
                    var nextCol = 0;
                    wsReport.Cells[startRow + nextRow, startCol + nextCol].Style = bgFormat;
                    wsReport.Cells[startRow + nextRow, startCol + nextCol].Value = pokerRow.UserName;
                    wsReport.Cells[startRow + nextRow, startCol + (nextCol += 1)].Style = bgFormat;
                    wsReport.Cells[startRow + nextRow, startCol + nextCol].Value = CastAide.AsDouble(pokerRow.GrossComm);
                    wsReport.Cells[startRow + nextRow, startCol + (nextCol += 1)].Style = bgFormat;
                    wsReport.Cells[startRow + nextRow, startCol + nextCol].Value = CastAide.AsDouble(pokerRow.MWinLoss);
                    wsReport.Cells[startRow + nextRow, startCol + (nextCol += 1)].Style = bgFormat;
                    wsReport.Cells[startRow + nextRow, startCol + nextCol].Value = CastAide.AsDouble(pokerRow.MComm);
                    wsReport.Cells[startRow + nextRow, startCol + (nextCol += 1)].Style = bgFormat;
                    wsReport.Cells[startRow + nextRow, startCol + nextCol].Value = CastAide.AsDouble(pokerRow.MTotal);
                    wsReport.Cells[startRow + nextRow, startCol + (nextCol += 1)].Style = bgFormatNegative;
                    wsReport.Cells[startRow + nextRow, startCol + nextCol].Value = CastAide.AsDouble(pokerRow.AgentComm);
                    wsReport.Cells[startRow + nextRow, startCol + (nextCol += 1)].Style = bgFormatNegative;
                    wsReport.Cells[startRow + nextRow, startCol + nextCol].Value = CastAide.AsDouble(pokerRow.MasterComm);
                    wsReport.Cells[startRow + nextRow, startCol + (nextCol += 1)].Style = bgFormatNegative;
                    wsReport.Cells[startRow + nextRow, startCol + nextCol].Value = CastAide.AsDouble(pokerRow.SuperComm);
                    wsReport.Cells[startRow + nextRow, startCol + (nextCol += 1)].Style = bgFormatNegative;
                    wsReport.Cells[startRow + nextRow, startCol + nextCol].Value = CastAide.AsDouble(pokerRow.CompanyComm);
                    wsReport.Cells[startRow + nextRow, startCol + (nextCol += 1)].Style = bgFormatNegative;
                    wsReport.Cells[startRow + nextRow, startCol + nextCol].Value = CastAide.AsDouble(pokerRow.GrossCommBase);
                    wsReport.Cells[startRow + nextRow, startCol + (nextCol += 1)].Style = bgFormatNegative;
                    wsReport.Cells[startRow + nextRow, startCol + nextCol].Value = CastAide.AsDouble(pokerRow.CompanyCommBase);

                    nextRow++;
                }
            }
        }

        #endregion export 2 excel
    }
